// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    W_WALLET c;

    function setUp() public {
        c = new W_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 amount, uint256 unlockTime, address caller) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: a non-zero contribution, a valid future unlock time,
        // and a caller who is not the test contract or zero address.
        vm.assume(caller != address(0) && caller != address(this));
        amount = bound(amount, 1, 10 ether);
        unlockTime = bound(unlockTime, 1, 1000);

        // Warp so the deposit is admissible and get one step closer to unlock.
        vm.warp(block.timestamp + 1);

        // The caller deposits Ether, becoming a holder with a balance and unlock time.
        vm.deal(caller, amount);
        vm.prank(caller);
        c.Put{value: amount}(unlockTime);

        // Advance beyond the unlock time so Collect can proceed.
        vm.warp(block.timestamp + unlockTime + 1);

        // Force the external value transfer to fail by having the caller
        // (msg.sender during Collect) reject the Ether refund. We do this with
        // a helper contract that always reverts when receiving Ether.
        Reverter reverter = new Reverter();
        vm.deal(address(reverter), amount);

        // The caller address used in Put must be the reverting contract so that
        // Collect's low-level call to msg.sender fails.
        vm.prank(address(reverter));
        c.Put{value: amount}(unlockTime);

        vm.warp(block.timestamp + unlockTime + 1);

        // Now trigger Collect. The reference contract only updates state after
        // a successful send; the mutant updates before the failed send.
        vm.prank(address(reverter));
        c.Collect(amount);

        // Read the holder's balance through the public getter.
        (uint256 storedUnlockTime, uint256 storedBalance) = c.Acc(address(reverter));

        // General invariant: the stored balance must still equal the net Ether
        // the caller contributed, because the send was never successful.
        // The reference keeps the balance, while the mutant subtracts it.
        assertTrue(storedBalance == amount);
    }
}

// Minimal adversarial counterparty: rejects all Ether transfers.
contract Reverter {
    receive() external payable {
        revert("no ether");
    }

    fallback() external payable {
        revert("no ether");
    }
}
